parameters.script:
// Poller (HNRSS): Hacker News job posts via the Algolia JSON API through the proxy, match keywords.
var now = Date.now();
var CUT = 48 * 60 * 60 * 1000;
function nodeJson(nodeName) {
  var n = $node[nodeName] ?? {};
  var j = n.json ?? null;
  if (j && typeof j === "object" && Object.keys(j).length > 0) return j;
  try {
    var al = (typeof n.all === "function") ? n.all() : n.all;
    if (Array.isArray(al) && al.length) {
      var x = (al[0] ?? {}).json ?? al[0];
      if (x && typeof x === "object" && Object.keys(x).length > 0) return x;
    }
  } catch (e) {}
  return {};
}
var prefNode = nodeJson("Get Preferences");
var prefResp = prefNode.output ?? prefNode;
var prefItems = ((((prefResp.data ?? {}).getJobPreferences ?? {}).items) ?? []);
var keywords = [];
var userId = "";
for (var i = 0; i < prefItems.length; i++) {
  var row = prefItems[i] ?? {};
  var u = String(row.UserId ?? "");
  var ks = String(row.Keywords ?? "").split(",").map(function (k) { return k.trim().toLowerCase(); }).filter(Boolean);
  if (u && ks.length && !userId) userId = u;
  for (var j = 0; j < ks.length; j++) if (keywords.indexOf(ks[j]) < 0) keywords.push(ks[j]);
}
if (!keywords.length || !userId) return [{ hit: false, dbg: "noprefs pc=" + prefItems.length + " kw=" + keywords.join("|") + " uid=" + (userId ? "Y" : "N") }];
var exNode = nodeJson("Existing Jobs");
var exResp = exNode.output ?? exNode;
var exItems = ((((exResp.data ?? {}).getMatchedJobs ?? {}).items) ?? []);
var seen = {};
for (var e = 0; e < exItems.length; e++) {
  var k0 = String((exItems[e] ?? {}).Url ?? "").trim().toLowerCase();
  if (k0) seen[k0] = true;
}
function stripHtml(s) {
  return String(s ?? "").replace(/<[^>]*>/g, " ").split(" ").filter(Boolean).join(" ");
}
function allOf(nodeName) {
  var n = $node[nodeName] ?? {};
  var al = (typeof n.all === "function") ? n.all() : n.all;
  al = Array.isArray(al) ? al : [];
  var arr = [];
  for (var q = 0; q < al.length; q++) {
    var x = (al[q] ?? {}).json ?? al[q];
    if (x) arr.push(x);
  }
  return arr;
}
// The proxy spreads a JSON object into one item per top-level key; find the item holding .hits.
var hits = [];
var feedArr = allOf("HN Feed");
for (var f = 0; f < feedArr.length; f++) {
  var obj = feedArr[f];
  if (obj && typeof obj === "object" && Array.isArray(obj.hits) && obj.hits.length > hits.length) hits = obj.hits;
}
var posts = [];
for (var c = 0; c < hits.length; c++) {
  var it = hits[c] ?? {};
  var title = String(it.title ?? "");
  var link = String(it.url ?? "");
  if (!link && it.objectID) link = "https://news.ycombinator.com/item?id=" + it.objectID;
  var pd = Date.parse(String(it.created_at ?? ""));
  if (!title || !link) continue;
  if (pd && now - pd > CUT) continue;
  var sn = stripHtml(it.story_text || it.comment_text || title).slice(0, 300);
  posts.push({ title: title, company: String(it.author ?? ""), url: link, snippet: sn, ts: pd || 0 });
}
posts.sort(function (x, y) { return (y.ts || 0) - (x.ts || 0); });
var out = [];
var runSeen = {};
for (var p = 0; p < posts.length && out.length < 10; p++) {
  var post = posts[p];
  var key = String(post.url ?? "").trim().toLowerCase();
  if (!key || seen[key] || runSeen[key]) continue;
  runSeen[key] = true;
  var hay = (post.title + " " + post.company + " " + post.snippet).toLowerCase();
  var matched = [];
  for (var m = 0; m < keywords.length; m++) if (hay.indexOf(keywords[m]) >= 0) matched.push(keywords[m]);
  if (!matched.length) continue;
  out.push({ hit: true, userId: userId, title: (post.title || "Untitled post").slice(0, 140), snippet: post.snippet, url: post.url, matchedOn: "hnrss |" + matched.join(", ") });
}
if (out.length) return out;
return [{ hit: false, dbg: JSON.stringify({ pc: prefItems.length, fh: feedArr.length, hits: hits.length, ex: exItems.length, p48: posts.length }).slice(0, 500) }];
